import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"周易集注 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"周易集注 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"zh/classics/jizhu/006.md","filePath":"zh/classics/jizhu/006.md"}'),l={name:"zh/classics/jizhu/006.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>偶者，阴之数也。坤者顺也，阴之性也。六画皆偶，则纯阴而顺之至矣，故不言地而言坤。马象乾，牝马，取其为干之配。牝马属阴，柔顺而从阳者也。马能行，顺而健者也，非顺外有健也，其健亦是顺之健也。坤利牝马之贞，与干不同者，何也?盖干以刚固为贞，坤以柔顺为贞，言如牝马之顺而不息则正矣。牝马地类，安得同干之贞，此占辞也，与乾卦元亨利贞同，但坤则贞利牝马耳。程子泥于四德，所以将利字作句，迷者，如迷失其道路也。坤为地，故曰迷，言占者君子，先干而行则失其主而迷错，后干而行则得其主而利矣。盖造化之理，阴从阳以生物，待唱而和者也。君为臣主，夫为妻主，后干即得所主矣，利孰大焉，其理本如此。观文言后得主而有常，此句可见矣。西南东北，以文王圆图卦位而言，阳气始于东北而盛于东南，阴气始于西南而盛于西北。西南乃坤之本乡，兑离巽三女同坤居之，故为得朋。震坎艮三男同乾居东北，则非女之朋矣，故丧朋。阴从其阳谓之正，惟丧其三女之朋，从乎其阳，则有生育之功，是能安于正也，安于其正故吉。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><h3 id="至哉坤元-万物资生-乃顺承天。" tabindex="-1">至哉坤元，万物资生，乃顺承天。 <a class="header-anchor" href="#至哉坤元-万物资生-乃顺承天。" aria-label="Permalink to “至哉坤元，万物资生，乃顺承天。”">​</a></h3><p>至者极也。天包乎地，故以大赞其大，而地止以至赞之，盖言地之至则与天同，而大则不及乎天也。元者四德之元，非干有元，而坤复又有一元也。干以施之，坤则受之，交接之间，一气而已。始者气之始，生者形之始，万物之形，皆生于地，然非地之自能为也。天所施之气至则生矣，故曰乃顺承天。乾健故一而施，坤顺故两而承，此释卦辞之元。</p><h3 id="坤厚载物-德合无疆-含弘光大-品物咸亨。" tabindex="-1">坤厚载物，德合无疆，含弘光大，品物咸亨。 <a class="header-anchor" href="#坤厚载物-德合无疆-含弘光大-品物咸亨。" aria-label="Permalink to “坤厚载物，德合无疆，含弘光大，品物咸亨。”">​</a></h3><p>坤厚载物，以德言，非以形言。德者载物厚德，含弘光大是也。无疆者干也，含者包容也，弘则是其所含者无物不有，以蕴畜而言也。其静也翕，故曰含弘。光者，昭明也。大则是其所光者，无远不届，以宣著而言也。其动也辟，故曰光大，言光大而必曰含弘者，不翕聚，则不能发散也。咸亨者，齐乎巽，相见乎离之时也，此释卦辞之亨。</p><h3 id="牝马地类-行地无疆-柔顺利贞。" tabindex="-1">牝马地类，行地无疆，柔顺利贞。 <a class="header-anchor" href="#牝马地类-行地无疆-柔顺利贞。" aria-label="Permalink to “牝马地类，行地无疆，柔顺利贞。”">​</a></h3><p>地属阴，牝阴物，故曰地类，又行地之物也。行地无疆，则顺而不息矣，此则柔顺所利之贞也，故利牝马之贞。此释卦辞牝马之贞。</p><h3 id="君子攸行-先迷失道-后顺得常。西南得朋-乃与类行。东北丧朋-乃终有庆。安贞之吉-应地无疆。" tabindex="-1">君子攸行，先迷失道，后顺得常。西南得朋，乃与类行。东北丧朋，乃终有庆。安贞之吉，应地无疆。 <a class="header-anchor" href="#君子攸行-先迷失道-后顺得常。西南得朋-乃与类行。东北丧朋-乃终有庆。安贞之吉-应地无疆。" aria-label="Permalink to “君子攸行，先迷失道，后顺得常。西南得朋，乃与类行。东北丧朋，乃终有庆。安贞之吉，应地无疆。”">​</a></h3><p>君子攸行，即文王卦辞，君子有攸往。言占者君子，有所往也。失道者，失其坤顺之道也。坤道主成，成在后，若先干而动，则迷而失道。得常者，得其坤顺之常。惟后干而动，则顺而得常。</p><p>夫惟坤贞，利在柔顺，是以君子有所往也。先则迷，后则得。西南虽得朋，不过与巽离兑三女同类而行耳，未足以为庆也。若丧乎三女之朋，能从乎阳，则有生物之功矣，终必有庆也。何也?盖柔顺从阳者，乃坤道之安于其正也，能安于其正，则阳施阴受，生物无疆，应乎地之无疆矣，所以乃终有庆也。此释卦辞，君子有攸往至安贞吉。</p><p>《象》曰：地势坤，君子以厚德载物。</p><p>西北高，东南低，顺流而下，地之势，本坤顺者也，故曰地势坤。且天地间持重载物，势力无有厚于地者，故下文曰厚。天以气运，故曰天行;地以形载，故曰地势。厚德载物者，以深厚之德，容载庶物也。若以厚德载物，体之身心，岂有他道哉?惟体吾长人之仁也，使一人得其愿，推而人人各得其愿，和吾利物之义也，使一事得其宜，推而事各得其宜，则我之德厚，而物无不载矣。此则孔子未发之意也。</p><p>初六，履霜，坚冰至。</p><p>六详见乾卦初九。霜，一阴之象。冰，六阴之象。方履霜而知坚冰至者，见占者防微杜渐，图之不可不早也。易为君子谋，干言勿用，即复卦闭关之义，欲君子之难进也。坤言坚冰，即姤卦女壮之戒，防小人之易长也。</p><h3 id="《象》曰-履霜坚冰-阴始凝也。驯致其道-至坚冰也。" tabindex="-1">《象》曰：履霜坚冰，阴始凝也。驯致其道，至坚冰也。 <a class="header-anchor" href="#《象》曰-履霜坚冰-阴始凝也。驯致其道-至坚冰也。" aria-label="Permalink to “《象》曰：履霜坚冰，阴始凝也。驯致其道，至坚冰也。”">​</a></h3><p>《易举正》：履霜之下，无坚冰二字。阴始凝而为霜，渐盛必至于坚冰，小人虽微，长则渐至于盛。驯者扰也，顺习也，道者，小人道长之道也，即上六其道穷也之道。驯习因循，渐至其阴道之盛，理势之必然也。</p><p>六二，直方大，不习无不利。</p><p>直字即坤至柔而动也刚之刚也，方字即至静而德方之方也，大字即含弘光大之大也。孔子彖辞，文言小象，皆本于此。前后之言，皆可相证。以本爻论，六二得坤道之正，则无私曲，故直。居坤之中，则地偏党，故方。直者在内，所存之柔顺中正也;方者在外，所处之柔顺中正也。惟柔顺中正，在内则为直，在外则为方，内而直，外而方，此其所以大也。不揉而直，不矩而方，不恢而大，此其所以不习也。若以人事论，直者内而天理为之主宰，无邪曲也。方者外而天理为之裁制，无偏倚也。大者无一念之不直，无一事之不方也。不习无不利者，直者自直，方者自方，大者自大，不思不勉，而中道也。利者，利有攸往之利，言不待学习，而自然直方大也。盖八卦正位，干在五，坤在二，皆圣人也。故乾刚健中正，则飞龙在天。坤柔顺中正，则不习无不利。占者有是德，方应是占矣。</p><h3 id="《象》曰-六二之动-直以方也。不习无不利-地道光也。" tabindex="-1">《象》曰：六二之动，直以方也。不习无不利，地道光也。 <a class="header-anchor" href="#《象》曰-六二之动-直以方也。不习无不利-地道光也。" aria-label="Permalink to “《象》曰：六二之动，直以方也。不习无不利，地道光也。”">​</a></h3><p>以字即而字，言直方之德，惟动可见，故曰坤至柔而动也刚。此则承天而动，生物之几也。若以人事论，心之动直而无私，事之动方而当理是也。地道光者，六二之柔顺中正，即地道也。地道柔顺中正，光之所发者，自然而然，不俟勉强，故曰不习无不利。光即含弘光大之光。</p><p>六三，含章可贞，或从王事，无成有终。</p><p>坤为吝啬，含之象也。刚柔相杂曰文，文之成者曰章，阳位而以阴居之，又坤为文章之象也。三居下卦之终，终之象也。或者不敢自决之辞，从者不敢造始之意。</p><p>三居下卦之上，有位者也，其道当含晦其章美，有美则归之于君，乃可常久而得正，或从上之事，不敢当其成功，惟奉职以终其事而已。爻有此象，故戒占者如此。</p><h3 id="《象》曰-含章可贞-以时发也。或从王事-知光大也。-知平声" tabindex="-1">《象》曰：含章可贞，以时发也。或从王事，知光大也。(知平声) <a class="header-anchor" href="#《象》曰-含章可贞-以时发也。或从王事-知光大也。-知平声" aria-label="Permalink to “《象》曰：含章可贞，以时发也。或从王事，知光大也。(知平声)”">​</a></h3><p>以时发者，言非终于韬晦，含藏不出，而有所为也。或从王事，带下一句说，孔子小象多是如此。知光大者，正指其无成有终也。盖含弘光大无成而代有终者地道也，地道与臣道相同。六三或从王事，无成有终者，盖知地道之光大，当如是也。</p><p>六四，括囊，无咎无誉。</p><p>坤为囊，阴虚能受，囊之象也。括者结囊口也，四变而奇，居下卦之上，结囊上口之象也。四近乎君，居多惧之地，不可妄咎妄誉，戒其作威福也。盖誉则有逼上之嫌，咎则有败事之累，惟晦藏其智，如结囊口，则不害矣。</p><p>六四柔顺得正，盖慎密不出者也，故有括囊之象，无咎之道也。然既不出，则亦无由辞赞其美矣，故其占如此。</p><h3 id="《象》曰-括囊无咎-慎不害也。" tabindex="-1">《象》曰：括囊无咎，慎不害也。 <a class="header-anchor" href="#《象》曰-括囊无咎-慎不害也。" aria-label="Permalink to “《象》曰：括囊无咎，慎不害也。”">​</a></h3><p>括囊者慎也，无咎者不害也。</p><p>六五，黄裳，元吉。</p><p>坤为黄为裳，黄裳之象也。黄中色，言其中也。裳下饰，言其顺也。黄字从五字来，裳字从六字来。</p><p>六五以阴居尊，中顺之德充诸内而见诸外，故有是象，而其占则元吉矣。刚自有刚德，柔自有柔德，本义是。</p><h3 id="《象》曰-黄裳元吉-文在中也。" tabindex="-1">《象》曰：黄裳元吉，文在中也。 <a class="header-anchor" href="#《象》曰-黄裳元吉-文在中也。" aria-label="Permalink to “《象》曰：黄裳元吉，文在中也。”">​</a></h3><p>坤为文，文也。居五之中，在中也。文在中言居坤之中也，所以黄裳元吉。</p><p>上六，龙战于野，其血玄黄。</p><p>六阳为龙，坤之错也，故阴阳皆可以言龙。且变艮综震，亦龙之象也。变艮为剥，阴阳相剥，战之象也。战于卦外，野之象也。血者龙之血也。坚冰至者所以防龙战之祸于其始，龙战野者，所以著坚冰之至于其终。</p><p>上六，阴盛之极，其道穷矣，穷则其势必争，至与阳战，两败俱伤，故有此象，凶可知矣。</p><h3 id="《象》曰-龙战于野-其道穷也。" tabindex="-1">《象》曰：龙战于野，其道穷也。 <a class="header-anchor" href="#《象》曰-龙战于野-其道穷也。" aria-label="Permalink to “《象》曰：龙战于野，其道穷也。”">​</a></h3><p>极则必穷，理势之必然也。</p><p>用六，利永贞。</p><p>用六，与用九同，此则以上六龙战于野言之。阴极则变阳矣，但阴柔恐不能固守，既变之后，惟长永贞而不为阴私所用，则亦如干之无不利矣。</p><h3 id="《象》曰-用六永贞-以大终也。" tabindex="-1">《象》曰：用六永贞，以大终也。 <a class="header-anchor" href="#《象》曰-用六永贞-以大终也。" aria-label="Permalink to “《象》曰：用六永贞，以大终也。”">​</a></h3><p>此美其善变也。阳大阴小，大者阳明之公，君子之道也。小者阴浊之私，小人之道也。今始阴浊而终阳明，小人而终君子，何大如之，故曰以大终也。</p><h2 id="文言" tabindex="-1">文言 <a class="header-anchor" href="#文言" aria-label="Permalink to “文言”">​</a></h2><h3 id="坤至柔而动也刚-至静而德方-后得主而有常-含万物而化光。坤道其顺乎-承天而时行。" tabindex="-1">坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行。 <a class="header-anchor" href="#坤至柔而动也刚-至静而德方-后得主而有常-含万物而化光。坤道其顺乎-承天而时行。" aria-label="Permalink to “坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行。”">​</a></h3><p>动者生物所动之机，德者生物所得之质。乾刚坤柔，定体也。坤固至柔矣，然干之施一至，坤即能翕，受而敷施之，其生物之机，不可止遏屈挠，此又柔中之刚矣。干动坤静，定体也。坤固至静矣，及其承乾之施，陶镕万类，各有定形，不可移易。有息者不可变为草木，无息者不可变为昆虫，此又静中之方矣。柔无为矣，而刚则能动。静无形矣，而方则有体。柔静者顺也体也，刚方者健也用也，后得主而有常者，后乎干则得干为主，乃坤道之常也。含万物而化光者，静翕之时，含万物生意于其中，及其动辟，则化生万物，而有光显也。坤道其顺乎，此句乃赞之也。坤之于干，犹臣妾之与夫君，亦惟听命而已。一施一受，不敢先时而起，亦不敢后时而不应，此所以赞其顺也。此以上申彖传之意。</p><h3 id="积善之家必有馀庆-积不善之家必有馀殃。臣弑其君-子弑其父-非一朝一夕之故-其所由来者渐矣-由辨之不早辨也。易曰-履霜-坚冰至-盖言顺也。" tabindex="-1">积善之家必有馀庆，积不善之家必有馀殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辨之不早辨也。易曰“履霜，坚冰至”，盖言顺也。 <a class="header-anchor" href="#积善之家必有馀庆-积不善之家必有馀殃。臣弑其君-子弑其父-非一朝一夕之故-其所由来者渐矣-由辨之不早辨也。易曰-履霜-坚冰至-盖言顺也。" aria-label="Permalink to “积善之家必有馀庆，积不善之家必有馀殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辨之不早辨也。易曰“履霜，坚冰至”，盖言顺也。”">​</a></h3><p>天下之事，未有不由积而成。家之所积者善，则福庆及于子孙。所积者不善，则灾殃流于后世。其大至于弑逆之祸，皆积累而至，非朝夕所能成也。由来者渐，言臣子也。辩之不早，责君父也。辩，察也，在下者不可不察之于己，在上者不可不察之于人。察之早，勿使之渐，则祸不作矣。顺字即驯字，驯致其道也，言顺习因循以至于坚冰也。前言驯致其道，此言盖言顺也，皆一意也，程传是。</p><h3 id="直其正也-方其义也。君子敬以直内-义以方外-敬义立而德不孤。直方大-不习无不利-则不疑其所行也。" tabindex="-1">直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。直方大，不习无不利，则不疑其所行也。 <a class="header-anchor" href="#直其正也-方其义也。君子敬以直内-义以方外-敬义立而德不孤。直方大-不习无不利-则不疑其所行也。" aria-label="Permalink to “直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。直方大，不习无不利，则不疑其所行也。”">​</a></h3><p>直者何也?言此心无邪曲之私，从绳墨而正之之谓也。方者何也?言此事无差谬之失，得裁制而宜之之谓也。此六二直方之所由名也。下则言求直方之功，人心惟有私，所以不直，如知其敬，乃吾性之礼存诸心者，以此敬为之操持，必使此心廓然大公，而无一毫人欲之私，则不期直而自直矣。人事惟有私，所以不方，如知其义，乃吾性之义见诸事者，以此义为之裁制，必使此事物来顺尖而无一毫人欲之私，则不期方而自方矣。德之偏者谓之孤，孤则不大矣。盖敬之至者，外必方，义之至者，内必直。内不直不足谓之义，不足谓义是德之孤也，今既有敬以涵义之体，又有义以达敬之用，则内外夹持，表里互养，日用之间，莫非天理之流行，德自充满盛大而不孤矣。何大如之?内而念念皆天理，则内不疑;外而事事皆天理，则外不疑。内外坦然而无疑，则畅于四支，不言而喻，发于事业，无所处而不当。何利如之?此所以不习无不利也。干言进修，坤言敬义，学圣人者，由于进修，欲进修者必先于敬义，乾坤二卦备矣。</p><h3 id="阴虽有美-含之。或从王事-弗敢成也。地道也-妻道也-臣道也。地道无成-而代有终也。" tabindex="-1">阴虽有美，含之。或从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。 <a class="header-anchor" href="#阴虽有美-含之。或从王事-弗敢成也。地道也-妻道也-臣道也。地道无成-而代有终也。" aria-label="Permalink to “阴虽有美，含之。或从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。”">​</a></h3><p>阴虽有美，含之，可以时发而从王事矣。或从王事，不敢有其成者，非其才有所不足不能成也，乃其分之所不敢成也。何也?法象莫大于天地，三纲莫重于夫妻君臣，天统乎地，夫统乎妻，君统乎臣，皆尊者唱而卑者和之。故地道也，妻道也，臣道也，皆不敢先自主也，皆如地之无成，惟代天之终耳。盖天能始物，不能终物，地继其后而终之，则地之所以有终者，终天之所未终也。地不敢专其成，而有其终，故曰无成而代有终也。六三为臣，故当如此。</p><h3 id="天地变化-草木蕃。天地闭-贤人隐。易曰-括囊-无咎无誉-盖言谨也。" tabindex="-1">天地变化，草木蕃。天地闭，贤人隐。易曰“括囊，无咎无誉”，盖言谨也。 <a class="header-anchor" href="#天地变化-草木蕃。天地闭-贤人隐。易曰-括囊-无咎无誉-盖言谨也。" aria-label="Permalink to “天地变化，草木蕃。天地闭，贤人隐。易曰“括囊，无咎无誉”，盖言谨也。”">​</a></h3><p>天地变化二句，乃引下文之辞，言天地变化，世道开泰，则草木之无知者且蕃茂，况于人乎，则贤人之必出而不隐可知矣。若天地闭，则贤人必敛德以避难，此其所以隐也。坤本阴卦，四六重阴，又不中，则阴之极矣。正天地闭塞，有阴而无阳，不能变化之时也，故当谨守不出者以此。</p><h3 id="君子黄中通理-正位居体-美在其中-而畅于四支-发于事业-美之至也。" tabindex="-1">君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。 <a class="header-anchor" href="#君子黄中通理-正位居体-美在其中-而畅于四支-发于事业-美之至也。" aria-label="Permalink to “君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。”">​</a></h3><p>黄者中德也，中者内也，黄中者中德之在内也。通者豁然脉络之贯通，无一毫私欲之滞塞也。理者井然文章之条理，无一毫私欲之混淆也。本爻既变坎为通，通之象也。本爻未变，坤为文，理之象也。故六五小《象》曰“文在中”。德之在内者，通而且理，爻之言黄者，以此正位，居尊位也。体者，坤之定体也。乾阳乃上体，坤阴乃下体，言虽在尊位，而居下体，故不曰衣而曰裳，爻之所以言裳者以此。以人事论，有居尊位而能谦下之意。此二句尽黄裳之义矣，又叹而赞之，以见元吉之故，言黄中美在其中，岂徒美哉。美既在中，则畅于四支，为日新之德，四体不言而喻者此美也。发于事业，为富有之业，天下国家无所处而不当者此美也，不其美之至乎。爻之所以不止言吉，而言元吉者以此。</p><h3 id="阴疑于阳必战-为其嫌于无阳也-故称龙焉。犹未离其类也-故称血焉。夫玄黄者天地之杂也-天玄而地黄。-为-于伪反。离-力智反。夫-音扶" tabindex="-1">阴疑于阳必战，为其嫌于无阳也，故称龙焉。犹未离其类也，故称血焉。夫玄黄者天地之杂也，天玄而地黄。(为，于伪反。离，力智反。夫，音扶) <a class="header-anchor" href="#阴疑于阳必战-为其嫌于无阳也-故称龙焉。犹未离其类也-故称血焉。夫玄黄者天地之杂也-天玄而地黄。-为-于伪反。离-力智反。夫-音扶" aria-label="Permalink to “阴疑于阳必战，为其嫌于无阳也，故称龙焉。犹未离其类也，故称血焉。夫玄黄者天地之杂也，天玄而地黄。(为，于伪反。离，力智反。夫，音扶)”">​</a></h3><p>疑者似也，似其与己均敌，无大小之差也。阴本不可与阳战，今阴盛似敢与阳敌，故以战言。阴盛已无阳矣，本不可以称龙，而不知阳不可一日无也，故周公以龙言之，以存阳也。虽称为龙，犹未离阴之类也，故称血，以别其为阴。血阴物也，曰其色玄黄，则天地之色杂矣，而不知天玄地黄者，两间之定分也。今曰其色玄黄，疑于无分别矣，夫岂可哉，言阴阳皆伤也。以上皆申言周公爻辞。</p>',61)])])}const f=e(l,[["render",p]]);export{b as __pageData,f as default};
